// One row per startup x investor pair that is a genuine match.
// 'Not per strategy' and 'Do-not-contact' rows are NOT matches and are skipped:
// matches.type is NOT NULL and there is no honest enum value for them.
// Upserts on the (startup_id, investor_id) unique key, so re-running is safe
// and no delete is needed.
const vr = $('GET pipeline').first().json.valueRanges[0].values;
const h = vr[0];
const rows = vr.slice(1).map(function (r) { var o = {}; h.forEach(function (k, i) { o[k] = r[i] === undefined ? '' : r[i]; }); return o; });
const nz = function (s) { return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const sMap = {}; for (const s of ($('GET startup ids').first().json.body || [])) { sMap[nz(s.name)] = s.id; }
const iMap = {}; for (const i of ($('GET investor ids').first().json.body || [])) { iMap[nz(i.name)] = i.id; }

function mtype(raw) {
  raw = String(raw || '');
  if (/stage\s+(?:one\s+step\s+)?off/i.test(raw)) return 'stage_off';
  if (/^\s*exact\s+match/i.test(raw)) return 'strict';
  if (/sector\s*\+\s*cheque\s+match/i.test(raw)) return 'sector_only';
  return null;
}
const PRI = { strict: 1, stage_off: 2, sector_only: 3 };
const seen = {}; const out = []; let skipped_notmatch = 0, skipped_noid = 0, dupes = 0;
for (const r of rows) {
  const t = mtype(r.match_type);
  if (!t) { skipped_notmatch++; continue; }
  const sid = sMap[nz(r.startup)], iid = iMap[nz(r.investor)];
  if (!sid || !iid) { skipped_noid++; continue; }
  const k = sid + ':' + iid;
  if (seen[k]) { dupes++; continue; }
  seen[k] = 1;
  const sent = String(r.deal_shared || '').trim().toLowerCase() === 'yes';
  const paused = !!String(r.pause || '').trim();
  const state = sent ? 'sent' : (paused ? 'paused' : 'queued');
  out.push({ startup_id: sid, investor_id: iid, type: t, state: state, priority: PRI[t],
             stage_fit: t !== 'stage_off', cheque_fit: true });
}
const CH = 700; const chunks = [];
for (let i = 0; i < out.length; i += CH) {
  chunks.push({ json: { rows: out.slice(i, i + CH), total: out.length,
    skipped_notmatch: skipped_notmatch, skipped_noid: skipped_noid, dupes: dupes,
    queued: out.filter(function (x) { return x.state === 'queued'; }).length,
    sent: out.filter(function (x) { return x.state === 'sent'; }).length,
    paused: out.filter(function (x) { return x.state === 'paused'; }).length } });
}
return chunks;

const b = $('Build matches').first().json;
const items = $input.all();
const bad = items.filter(function (i) { return !(i.json.statusCode >= 200 && i.json.statusCode < 300); });
return [{ json: { matches_built: b.total, queued: b.queued, sent: b.sent, paused: b.paused,
  chunks: items.length, statuses: items.map(function (i) { return i.json.statusCode; }),
  failed: bad.length, errors: bad.map(function (i) { return JSON.stringify(i.json.body).slice(0, 200); }).slice(0, 3),
  skipped_not_a_match: b.skipped_notmatch, skipped_name_not_found: b.skipped_noid, duplicate_pairs: b.dupes } }];
